-- Tablas del modulo M1 (19 tablas). Se ejecuta como BD_ENLACE_EXPRESS.
-- Base: docs/datamodeler/modulo_envios_datamodeler.ddl (Data Modeler 24.3).
-- Cambios respecto al DDL exportado: semantica de longitud en caracteres,
-- columnas de identidad (GENERATED BY DEFAULT) en las 14 tablas con clave
-- sustituta, TABLESPACE de datos en cada tabla y USING INDEX TABLESPACE
-- de indices en cada PK y UNIQUE. Sin encabezado ni resumen de Data Modeler.
WHENEVER SQLERROR EXIT FAILURE
SET DEFINE OFF

ALTER SESSION SET NLS_LENGTH_SEMANTICS = CHAR;

CREATE TABLE ASIGNACION_DESPACHO 
    ( 
     ID_ASIGNACION  NUMBER (12) GENERATED BY DEFAULT AS IDENTITY NOT NULL , 
     NUMERO_GUIA    VARCHAR2 (15)  NOT NULL , 
     ID_DESPACHO    NUMBER (10)  NOT NULL , 
     NUMERO_INTENTO NUMBER (1)  NOT NULL , 
     ORDEN_VISITA   NUMBER (3)  NOT NULL , 
     HORA_VISITA    TIMESTAMP , 
     RESULTADO      VARCHAR2 (12) DEFAULT 'PENDIENTE'  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

ALTER TABLE ASIGNACION_DESPACHO 
    ADD CONSTRAINT ASIGNACION_INTENTO_CK 
    CHECK (NUMERO_INTENTO BETWEEN 1 AND 3) 
;

ALTER TABLE ASIGNACION_DESPACHO 
    ADD CONSTRAINT ASIGNACION_ORDEN_CK 
    CHECK (ORDEN_VISITA > 0) 
;

ALTER TABLE ASIGNACION_DESPACHO 
    ADD CONSTRAINT ASIGNACION_RESULTADO_CK 
    CHECK (RESULTADO IN ('DEVUELTO', 'ENTREGADO', 'NOVEDAD', 'PENDIENTE')) 
;

COMMENT ON TABLE ASIGNACION_DESPACHO IS 'Cada intento de un envío en un despacho.'
;

COMMENT ON COLUMN ASIGNACION_DESPACHO.ID_ASIGNACION IS 'Identificador' 
;

COMMENT ON COLUMN ASIGNACION_DESPACHO.NUMERO_GUIA IS 'Envío (ref. envio)' 
;

COMMENT ON COLUMN ASIGNACION_DESPACHO.ID_DESPACHO IS 'Despacho (ref. despacho)' 
;

COMMENT ON COLUMN ASIGNACION_DESPACHO.NUMERO_INTENTO IS '1 y 2: entrega; 3: devolución' 
;

COMMENT ON COLUMN ASIGNACION_DESPACHO.ORDEN_VISITA IS 'Orden de visita en la ruta' 
;

COMMENT ON COLUMN ASIGNACION_DESPACHO.HORA_VISITA IS 'Hora en que se visitó' 
;

COMMENT ON COLUMN ASIGNACION_DESPACHO.RESULTADO IS 'PENDIENTE, ENTREGADO, NOVEDAD o DEVUELTO; por defecto PENDIENTE' 
;

ALTER TABLE ASIGNACION_DESPACHO 
    ADD CONSTRAINT ASIGNACION_PK PRIMARY KEY ( ID_ASIGNACION )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

ALTER TABLE ASIGNACION_DESPACHO 
    ADD CONSTRAINT ASIGNACION_ENVIO_DESP_UK UNIQUE ( NUMERO_GUIA , ID_DESPACHO )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

ALTER TABLE ASIGNACION_DESPACHO 
    ADD CONSTRAINT ASIGNACION_INTENTO_UK UNIQUE ( NUMERO_GUIA , NUMERO_INTENTO )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE CENTRO_DISTRIBUCION 
    ( 
     ID_CENTRO NUMBER (5) GENERATED BY DEFAULT AS IDENTITY NOT NULL , 
     NOMBRE    VARCHAR2 (60)  NOT NULL , 
     DIRECCION VARCHAR2 (120)  NOT NULL , 
     TELEFONO  VARCHAR2 (20) , 
     ESTADO    VARCHAR2 (10) DEFAULT 'ACTIVO'  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

ALTER TABLE CENTRO_DISTRIBUCION 
    ADD CONSTRAINT CENTRO_ESTADO_CK 
    CHECK (ESTADO IN ('ACTIVO', 'INACTIVO')) 
;

COMMENT ON TABLE CENTRO_DISTRIBUCION IS 'Centro donde se reciben, clasifican y despachan los envíos.'
;

COMMENT ON COLUMN CENTRO_DISTRIBUCION.ID_CENTRO IS 'Identificador del centro' 
;

COMMENT ON COLUMN CENTRO_DISTRIBUCION.NOMBRE IS 'Nombre del centro' 
;

COMMENT ON COLUMN CENTRO_DISTRIBUCION.DIRECCION IS 'Dirección' 
;

COMMENT ON COLUMN CENTRO_DISTRIBUCION.TELEFONO IS 'Teléfono de contacto' 
;

COMMENT ON COLUMN CENTRO_DISTRIBUCION.ESTADO IS 'ACTIVO o INACTIVO; por defecto ACTIVO' 
;

ALTER TABLE CENTRO_DISTRIBUCION 
    ADD CONSTRAINT CENTRO_PK PRIMARY KEY ( ID_CENTRO )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

ALTER TABLE CENTRO_DISTRIBUCION 
    ADD CONSTRAINT CENTRO_NOMBRE_UK UNIQUE ( NOMBRE )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE CLIENTE 
    ( 
     ID_CLIENTE        NUMBER (10) GENERATED BY DEFAULT AS IDENTITY NOT NULL , 
     NIT               VARCHAR2 (15)  NOT NULL , 
     RAZON_SOCIAL      VARCHAR2 (120)  NOT NULL , 
     TIPO_CLIENTE      VARCHAR2 (15)  NOT NULL , 
     TELEFONO          VARCHAR2 (20)  NOT NULL , 
     CORREO            VARCHAR2 (100)  NOT NULL , 
     FECHA_VINCULACION DATE  NOT NULL , 
     ESTADO            VARCHAR2 (10) DEFAULT 'ACTIVO'  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

ALTER TABLE CLIENTE 
    ADD CONSTRAINT CLIENTE_TIPO_CK 
    CHECK (TIPO_CLIENTE IN ('DROGUERIA', 'OFICINA', 'TIENDA_LINEA')) 
;

ALTER TABLE CLIENTE 
    ADD CONSTRAINT CLIENTE_ESTADO_CK 
    CHECK (ESTADO IN ('ACTIVO', 'INACTIVO')) 
;

COMMENT ON TABLE CLIENTE IS 'Empresa que contrata el servicio.'
;

COMMENT ON COLUMN CLIENTE.ID_CLIENTE IS 'Identificador del cliente' 
;

COMMENT ON COLUMN CLIENTE.NIT IS 'NIT' 
;

COMMENT ON COLUMN CLIENTE.RAZON_SOCIAL IS 'Razón social' 
;

COMMENT ON COLUMN CLIENTE.TIPO_CLIENTE IS 'TIENDA_LINEA, DROGUERIA u OFICINA' 
;

COMMENT ON COLUMN CLIENTE.TELEFONO IS 'Teléfono' 
;

COMMENT ON COLUMN CLIENTE.CORREO IS 'Correo electrónico' 
;

COMMENT ON COLUMN CLIENTE.FECHA_VINCULACION IS 'Fecha de vinculación' 
;

COMMENT ON COLUMN CLIENTE.ESTADO IS 'ACTIVO o INACTIVO; por defecto ACTIVO' 
;

ALTER TABLE CLIENTE 
    ADD CONSTRAINT CLIENTE_PK PRIMARY KEY ( ID_CLIENTE )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

ALTER TABLE CLIENTE 
    ADD CONSTRAINT CLIENTE_NIT_UK UNIQUE ( NIT )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE DESPACHO 
    ( 
     ID_DESPACHO  NUMBER (10) GENERATED BY DEFAULT AS IDENTITY NOT NULL , 
     ID_CENTRO    NUMBER (5)  NOT NULL , 
     ID_VEHICULO  NUMBER (5)  NOT NULL , 
     ID_MENSAJERO NUMBER (10)  NOT NULL , 
     FECHA        DATE  NOT NULL , 
     TIPO         VARCHAR2 (12)  NOT NULL , 
     HORA_SALIDA  TIMESTAMP , 
     HORA_CIERRE  TIMESTAMP , 
     ESTADO       VARCHAR2 (10) DEFAULT 'ARMADO'  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

ALTER TABLE DESPACHO 
    ADD CONSTRAINT DESPACHO_TIPO_CK 
    CHECK (TIPO IN ('ENTREGA', 'RECOLECCION')) 
;

ALTER TABLE DESPACHO 
    ADD CONSTRAINT DESPACHO_ESTADO_CK 
    CHECK (ESTADO IN ('ARMADO', 'CERRADO', 'EN_RUTA')) 
;

COMMENT ON TABLE DESPACHO IS 'Salida de un mensajero con un vehículo.'
;

COMMENT ON COLUMN DESPACHO.ID_DESPACHO IS 'Identificador' 
;

COMMENT ON COLUMN DESPACHO.ID_CENTRO IS 'Centro de origen (ref. centro_distribucion)' 
;

COMMENT ON COLUMN DESPACHO.ID_VEHICULO IS 'Vehículo asignado (ref. vehiculo)' 
;

COMMENT ON COLUMN DESPACHO.ID_MENSAJERO IS 'Mensajero asignado (ref. mensajero)' 
;

COMMENT ON COLUMN DESPACHO.FECHA IS 'Fecha del despacho' 
;

COMMENT ON COLUMN DESPACHO.TIPO IS 'RECOLECCION o ENTREGA' 
;

COMMENT ON COLUMN DESPACHO.HORA_SALIDA IS 'Hora de salida' 
;

COMMENT ON COLUMN DESPACHO.HORA_CIERRE IS 'Hora de cierre de la ruta' 
;

COMMENT ON COLUMN DESPACHO.ESTADO IS 'ARMADO, EN_RUTA o CERRADO; por defecto ARMADO' 
;

ALTER TABLE DESPACHO 
    ADD CONSTRAINT DESPACHO_HORAS_CK 
    CHECK (HORA_CIERRE IS NULL OR HORA_CIERRE > HORA_SALIDA)
;
ALTER TABLE DESPACHO 
    ADD CONSTRAINT DESPACHO_PK PRIMARY KEY ( ID_DESPACHO )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE DESTINATARIO 
    ( 
     ID_DESTINATARIO  NUMBER (12) GENERATED BY DEFAULT AS IDENTITY NOT NULL , 
     TIPO_DOCUMENTO   VARCHAR2 (3)  NOT NULL , 
     NUMERO_DOCUMENTO VARCHAR2 (15)  NOT NULL , 
     NOMBRE           VARCHAR2 (100)  NOT NULL , 
     TELEFONO         VARCHAR2 (20)  NOT NULL , 
     CORREO           VARCHAR2 (100) 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

ALTER TABLE DESTINATARIO 
    ADD CONSTRAINT DESTINATARIO_TIPO_DOC_CK 
    CHECK (TIPO_DOCUMENTO IN ('CC', 'CE', 'NIT', 'PAS', 'TI')) 
;

