;

COMMENT ON COLUMN DESTINATARIO.ID_DESTINATARIO IS 'Identificador' 
;

COMMENT ON COLUMN DESTINATARIO.TIPO_DOCUMENTO IS 'CC, CE, NIT, PAS o TI' 
;

COMMENT ON COLUMN DESTINATARIO.NUMERO_DOCUMENTO IS 'Número de documento' 
;

COMMENT ON COLUMN DESTINATARIO.NOMBRE IS 'Nombre completo' 
;

COMMENT ON COLUMN DESTINATARIO.TELEFONO IS 'Teléfono' 
;

COMMENT ON COLUMN DESTINATARIO.CORREO IS 'Correo electrónico' 
;

ALTER TABLE DESTINATARIO 
    ADD CONSTRAINT DESTINATARIO_PK PRIMARY KEY ( ID_DESTINATARIO )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

ALTER TABLE DESTINATARIO 
    ADD CONSTRAINT DESTINATARIO_DOCUMENTO_UK UNIQUE ( TIPO_DOCUMENTO , NUMERO_DOCUMENTO )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE EMPLEADO 
    ( 
     ID_EMPLEADO   NUMBER (10) GENERATED BY DEFAULT AS IDENTITY NOT NULL , 
     ID_CENTRO     NUMBER (5)  NOT NULL , 
     DOCUMENTO     VARCHAR2 (15)  NOT NULL , 
     NOMBRES       VARCHAR2 (60)  NOT NULL , 
     APELLIDOS     VARCHAR2 (60)  NOT NULL , 
     CARGO         VARCHAR2 (40)  NOT NULL , 
     TELEFONO      VARCHAR2 (20)  NOT NULL , 
     CORREO        VARCHAR2 (100) , 
     FECHA_INGRESO DATE  NOT NULL , 
     FECHA_RETIRO  DATE , 
     MOTIVO_RETIRO VARCHAR2 (200) , 
     ESTADO        VARCHAR2 (10) DEFAULT 'ACTIVO'  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

ALTER TABLE EMPLEADO 
    ADD CONSTRAINT EMPLEADO_ESTADO_CK 
    CHECK (ESTADO IN ('ACTIVO', 'RETIRADO')) 
;

COMMENT ON TABLE EMPLEADO IS 'Persona vinculada a la empresa.'
;

COMMENT ON COLUMN EMPLEADO.ID_EMPLEADO IS 'Identificador' 
;

COMMENT ON COLUMN EMPLEADO.ID_CENTRO IS 'Centro donde labora (ref. centro_distribucion)' 
;

COMMENT ON COLUMN EMPLEADO.DOCUMENTO IS 'Documento de identidad' 
;

COMMENT ON COLUMN EMPLEADO.NOMBRES IS 'Nombres' 
;

COMMENT ON COLUMN EMPLEADO.APELLIDOS IS 'Apellidos' 
;

COMMENT ON COLUMN EMPLEADO.CARGO IS 'Cargo' 
;

COMMENT ON COLUMN EMPLEADO.TELEFONO IS 'Teléfono' 
;

COMMENT ON COLUMN EMPLEADO.CORREO IS 'Correo electrónico' 
;

COMMENT ON COLUMN EMPLEADO.FECHA_INGRESO IS 'Fecha de ingreso' 
;

COMMENT ON COLUMN EMPLEADO.FECHA_RETIRO IS 'Fecha de retiro' 
;

COMMENT ON COLUMN EMPLEADO.MOTIVO_RETIRO IS 'Motivo del retiro' 
;

COMMENT ON COLUMN EMPLEADO.ESTADO IS 'ACTIVO o RETIRADO; por defecto ACTIVO' 
;

ALTER TABLE EMPLEADO 
    ADD CONSTRAINT EMPLEADO_RETIRO_CK 
    CHECK (FECHA_RETIRO IS NULL OR FECHA_RETIRO >= FECHA_INGRESO)
;
ALTER TABLE EMPLEADO 
    ADD CONSTRAINT EMPLEADO_PK PRIMARY KEY ( ID_EMPLEADO )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

ALTER TABLE EMPLEADO 
    ADD CONSTRAINT EMPLEADO_DOCUMENTO_UK UNIQUE ( DOCUMENTO )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE ENVIO 
    ( 
     NUMERO_GUIA       VARCHAR2 (15)  NOT NULL , 
     ID_SOLICITUD      NUMBER (10)  NOT NULL , 
     ID_DESTINATARIO   NUMBER (12)  NOT NULL , 
     ID_ZONA           NUMBER (5)  NOT NULL , 
     ID_MODALIDAD      NUMBER (2)  NOT NULL , 
     FECHA_REGISTRO    DATE  NOT NULL , 
     DIRECCION_DESTINO VARCHAR2 (150)  NOT NULL , 
     PESO_DECLARADO    NUMBER (6,2)  NOT NULL , 
     PESO_REAL         NUMBER (6,2) , 
     CONTENIDO         VARCHAR2 (150)  NOT NULL , 
     VALOR_DECLARADO   NUMBER (12,2)  NOT NULL , 
     FRAGIL            CHAR (1) DEFAULT 'N'  NOT NULL , 
     ALTO_VALOR        CHAR (1) DEFAULT 'N'  NOT NULL , 
     VALOR_FLETE       NUMBER (12,2) , 
     FECHA_COMPROMISO  DATE  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

ALTER TABLE ENVIO 
    ADD CONSTRAINT ENVIO_FRAGIL_CK 
    CHECK (FRAGIL IN ('N', 'S')) 
;

ALTER TABLE ENVIO 
    ADD CONSTRAINT ENVIO_ALTO_VALOR_CK 
    CHECK (ALTO_VALOR IN ('N', 'S')) 
;

COMMENT ON TABLE ENVIO IS 'Paquete o documento identificado por su guía.'
;

COMMENT ON COLUMN ENVIO.NUMERO_GUIA IS 'Número de guía' 
;

COMMENT ON COLUMN ENVIO.ID_SOLICITUD IS 'Solicitud en la que se recoge (ref. solicitud_recoleccion)' 
;

COMMENT ON COLUMN ENVIO.ID_DESTINATARIO IS 'Destinatario (ref. destinatario)' 
;

COMMENT ON COLUMN ENVIO.ID_ZONA IS 'Zona de destino (ref. zona)' 
;

COMMENT ON COLUMN ENVIO.ID_MODALIDAD IS 'Modalidad contratada (ref. modalidad)' 
;

COMMENT ON COLUMN ENVIO.FECHA_REGISTRO IS 'Fecha de registro' 
;

COMMENT ON COLUMN ENVIO.DIRECCION_DESTINO IS 'Dirección de entrega' 
;

COMMENT ON COLUMN ENVIO.PESO_DECLARADO IS 'Peso declarado en kg' 
;

COMMENT ON COLUMN ENVIO.PESO_REAL IS 'Peso verificado en el centro' 
;

COMMENT ON COLUMN ENVIO.CONTENIDO IS 'Descripción del contenido' 
;

COMMENT ON COLUMN ENVIO.VALOR_DECLARADO IS 'Valor declarado' 
;

COMMENT ON COLUMN ENVIO.FRAGIL IS 'S o N; por defecto N' 
;

COMMENT ON COLUMN ENVIO.ALTO_VALOR IS 'S o N; por defecto N' 
;

COMMENT ON COLUMN ENVIO.VALOR_FLETE IS 'Valor cobrado por el envío' 
;

COMMENT ON COLUMN ENVIO.FECHA_COMPROMISO IS 'Fecha máxima de entrega' 
;

ALTER TABLE ENVIO 
    ADD CONSTRAINT ENVIO_COMPROMISO_CK 
    CHECK (FECHA_COMPROMISO >= FECHA_REGISTRO)
;


ALTER TABLE ENVIO 
    ADD CONSTRAINT ENVIO_PESOS_CK 
    CHECK (PESO_DECLARADO > 0 AND (PESO_REAL IS NULL OR PESO_REAL > 0))
;


ALTER TABLE ENVIO 
    ADD CONSTRAINT ENVIO_VALOR_CK 
    CHECK (VALOR_DECLARADO >= 0 AND (VALOR_FLETE IS NULL OR VALOR_FLETE > 0))
;
ALTER TABLE ENVIO 
    ADD CONSTRAINT ENVIO_PK PRIMARY KEY ( NUMERO_GUIA )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE ESTADO_ENVIO 
    ( 
     ID_ESTADO NUMBER (2)  NOT NULL , 
     NOMBRE    VARCHAR2 (20)  NOT NULL , 
     ES_FINAL  CHAR (1) DEFAULT 'N'  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

ALTER TABLE ESTADO_ENVIO 
    ADD CONSTRAINT ESTADO_ENVIO_FINAL_CK 
    CHECK (ES_FINAL IN ('N', 'S')) 
;

COMMENT ON TABLE ESTADO_ENVIO IS 'Catálogo de estados del envío.'
;

COMMENT ON COLUMN ESTADO_ENVIO.ID_ESTADO IS 'Identificador' 
;

COMMENT ON COLUMN ESTADO_ENVIO.NOMBRE IS 'Nombre del estado' 
;

COMMENT ON COLUMN ESTADO_ENVIO.ES_FINAL IS 'S si el envío ya no cambia de estado; por defecto N' 
;

ALTER TABLE ESTADO_ENVIO 
    ADD CONSTRAINT ESTADO_ENVIO_PK PRIMARY KEY ( ID_ESTADO )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

ALTER TABLE ESTADO_ENVIO 
    ADD CONSTRAINT ESTADO_ENVIO_NOMBRE_UK UNIQUE ( NOMBRE )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

