CREATE TABLE MODALIDAD 
    ( 
     ID_MODALIDAD       NUMBER (2)  NOT NULL , 
     NOMBRE             VARCHAR2 (30)  NOT NULL , 
     PLAZO_DIAS_HABILES NUMBER (1)  NOT NULL 
