ALTER TABLE MODALIDAD 
    ADD CONSTRAINT MODALIDAD_NOMBRE_UK UNIQUE ( NOMBRE )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE NOVEDAD 
    ( 
     ID_NOVEDAD    NUMBER (10) GENERATED BY DEFAULT AS IDENTITY NOT NULL , 
