ALTER TABLE NOVEDAD 
    ADD CONSTRAINT NOVEDAD_PK PRIMARY KEY ( ID_NOVEDAD )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

ALTER TABLE NOVEDAD 
    ADD CONSTRAINT NOVEDAD_ASIGNACION_UK UNIQUE ( ID_ASIGNACION )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

