;

COMMENT ON COLUMN PRUEBA_ENTREGA.ID_ASIGNACION IS 'Intento al que corresponde (ref. asignacion_despacho)' 
;

COMMENT ON COLUMN PRUEBA_ENTREGA.FECHA_HORA IS 'Fecha y hora de recibo' 
;

COMMENT ON COLUMN PRUEBA_ENTREGA.NOMBRE_RECEPTOR IS 'Quién recibe' 
;

COMMENT ON COLUMN PRUEBA_ENTREGA.DOCUMENTO_RECEPTOR IS 'Documento de quien recibe' 
;

COMMENT ON COLUMN PRUEBA_ENTREGA.TIPO_PRUEBA IS 'FIRMA, DOCUMENTO o FOTOGRAFIA' 
;

COMMENT ON COLUMN PRUEBA_ENTREGA.ARCHIVO_SOPORTE IS 'Ruta del archivo de soporte' 
;

ALTER TABLE PRUEBA_ENTREGA 
    ADD CONSTRAINT PRUEBA_PK PRIMARY KEY ( ID_PRUEBA )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

ALTER TABLE PRUEBA_ENTREGA 
    ADD CONSTRAINT PRUEBA_ASIGNACION_UK UNIQUE ( ID_ASIGNACION )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE RECLAMACION 
    ( 
     ID_RECLAMACION   NUMBER (10) GENERATED BY DEFAULT AS IDENTITY NOT NULL , 
     ID_CLIENTE       NUMBER (10)  NOT NULL , 
     NUMERO_GUIA      VARCHAR2 (15) , 
     FECHA_RADICACION TIMESTAMP  NOT NULL , 
     TIPO             VARCHAR2 (15)  NOT NULL , 
     DESCRIPCION      VARCHAR2 (500)  NOT NULL , 
     RESPUESTA        VARCHAR2 (500) , 
     FECHA_RESPUESTA  TIMESTAMP , 
     ESTADO           VARCHAR2 (10) DEFAULT 'ABIERTA'  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

ALTER TABLE RECLAMACION 
    ADD CONSTRAINT RECLAMACION_TIPO_CK 
    CHECK (TIPO IN ('DANO', 'ENTREGA', 'FACTURACION', 'OTRO')) 
;

ALTER TABLE RECLAMACION 
    ADD CONSTRAINT RECLAMACION_ESTADO_CK 
    CHECK (ESTADO IN ('ABIERTA', 'CERRADA', 'RESPONDIDA')) 
;

COMMENT ON TABLE RECLAMACION IS 'Inconformidad de un cliente.'
;

COMMENT ON COLUMN RECLAMACION.ID_RECLAMACION IS 'Identificador' 
;

COMMENT ON COLUMN RECLAMACION.ID_CLIENTE IS 'Cliente que reclama (ref. cliente)' 
;

COMMENT ON COLUMN RECLAMACION.NUMERO_GUIA IS 'Envío reclamado (opcional) (ref. envio)' 
;

COMMENT ON COLUMN RECLAMACION.FECHA_RADICACION IS 'Fecha y hora de radicación' 
;

COMMENT ON COLUMN RECLAMACION.TIPO IS 'ENTREGA, DANO, FACTURACION u OTRO' 
;

COMMENT ON COLUMN RECLAMACION.DESCRIPCION IS 'Descripción' 
;

COMMENT ON COLUMN RECLAMACION.RESPUESTA IS 'Respuesta dada' 
;

COMMENT ON COLUMN RECLAMACION.FECHA_RESPUESTA IS 'Fecha y hora de respuesta' 
;

COMMENT ON COLUMN RECLAMACION.ESTADO IS 'ABIERTA, RESPONDIDA o CERRADA; por defecto ABIERTA' 
;

ALTER TABLE RECLAMACION 
    ADD CONSTRAINT RECLAMACION_RESP_CK 
    CHECK (FECHA_RESPUESTA IS NULL OR FECHA_RESPUESTA >= FECHA_RADICACION)
;
ALTER TABLE RECLAMACION 
    ADD CONSTRAINT RECLAMACION_PK PRIMARY KEY ( ID_RECLAMACION )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE SEDE_CLIENTE 
    ( 
     ID_SEDE    NUMBER (10) GENERATED BY DEFAULT AS IDENTITY NOT NULL , 
     ID_CLIENTE NUMBER (10)  NOT NULL , 
     ID_ZONA    NUMBER (5)  NOT NULL , 
     NOMBRE     VARCHAR2 (60)  NOT NULL , 
     DIRECCION  VARCHAR2 (120)  NOT NULL , 
     CONTACTO   VARCHAR2 (80)  NOT NULL , 
     TELEFONO   VARCHAR2 (20)  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

COMMENT ON TABLE SEDE_CLIENTE IS 'Punto de recolección de un cliente.'
;

COMMENT ON COLUMN SEDE_CLIENTE.ID_SEDE IS 'Identificador de la sede' 
;

COMMENT ON COLUMN SEDE_CLIENTE.ID_CLIENTE IS 'Cliente dueño de la sede (ref. cliente)' 
;

COMMENT ON COLUMN SEDE_CLIENTE.ID_ZONA IS 'Zona donde está la sede (ref. zona)' 
;

COMMENT ON COLUMN SEDE_CLIENTE.NOMBRE IS 'Nombre de la sede' 
;

COMMENT ON COLUMN SEDE_CLIENTE.DIRECCION IS 'Dirección' 
;

COMMENT ON COLUMN SEDE_CLIENTE.CONTACTO IS 'Persona de contacto' 
;

COMMENT ON COLUMN SEDE_CLIENTE.TELEFONO IS 'Teléfono' 
;

ALTER TABLE SEDE_CLIENTE 
    ADD CONSTRAINT SEDE_PK PRIMARY KEY ( ID_SEDE )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE SOLICITUD_RECOLECCION 
    ( 
     ID_SOLICITUD     NUMBER (10) GENERATED BY DEFAULT AS IDENTITY NOT NULL , 
     ID_SEDE          NUMBER (10)  NOT NULL , 
     ID_DESPACHO      NUMBER (10) , 
     FECHA_SOLICITUD  DATE  NOT NULL , 
     FECHA_PROGRAMADA DATE  NOT NULL , 
     FRANJA_HORARIA   VARCHAR2 (10)  NOT NULL , 
     ESTADO           VARCHAR2 (12) DEFAULT 'PENDIENTE'  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

ALTER TABLE SOLICITUD_RECOLECCION 
    ADD CONSTRAINT SOLICITUD_FRANJA_CK 
    CHECK (FRANJA_HORARIA IN ('MANANA', 'TARDE')) 
;

ALTER TABLE SOLICITUD_RECOLECCION 
    ADD CONSTRAINT SOLICITUD_ESTADO_CK 
    CHECK (ESTADO IN ('ATENDIDA', 'NO_ATENDIDA', 'PENDIENTE', 'PROGRAMADA')) 
;

COMMENT ON TABLE SOLICITUD_RECOLECCION IS 'Pedido de recolección en una sede del cliente.'
;

COMMENT ON COLUMN SOLICITUD_RECOLECCION.ID_SOLICITUD IS 'Identificador' 
;

COMMENT ON COLUMN SOLICITUD_RECOLECCION.ID_SEDE IS 'Sede donde se recoge (ref. sede_cliente)' 
;

COMMENT ON COLUMN SOLICITUD_RECOLECCION.ID_DESPACHO IS 'Despacho de recolección (al programarla) (ref. despacho)' 
;

COMMENT ON COLUMN SOLICITUD_RECOLECCION.FECHA_SOLICITUD IS 'Fecha en que se pide' 
;

COMMENT ON COLUMN SOLICITUD_RECOLECCION.FECHA_PROGRAMADA IS 'Fecha de recolección' 
;

COMMENT ON COLUMN SOLICITUD_RECOLECCION.FRANJA_HORARIA IS 'MANANA o TARDE' 
;

COMMENT ON COLUMN SOLICITUD_RECOLECCION.ESTADO IS 'PENDIENTE, PROGRAMADA, ATENDIDA o NO_ATENDIDA; por defecto PENDIENTE' 
;

ALTER TABLE SOLICITUD_RECOLECCION 
    ADD CONSTRAINT SOLICITUD_FECHAS_CK 
    CHECK (FECHA_PROGRAMADA >= FECHA_SOLICITUD)
;
ALTER TABLE SOLICITUD_RECOLECCION 
    ADD CONSTRAINT SOLICITUD_PK PRIMARY KEY ( ID_SOLICITUD )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE TIPO_VEHICULO 
    ( 
     ID_TIPO_VEHICULO NUMBER (2)  NOT NULL , 
     NOMBRE           VARCHAR2 (30)  NOT NULL , 
     CAPACIDAD_MAX_KG NUMBER (6,1)  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

ALTER TABLE TIPO_VEHICULO 
    ADD CONSTRAINT TIPO_VEHICULO_CAPACIDAD_CK 
    CHECK (CAPACIDAD_MAX_KG > 0) 
;

COMMENT ON TABLE TIPO_VEHICULO IS 'Catálogo de tipos de vehículo.'
;

COMMENT ON COLUMN TIPO_VEHICULO.ID_TIPO_VEHICULO IS 'Identificador' 
;

COMMENT ON COLUMN TIPO_VEHICULO.NOMBRE IS 'MOTOCICLETA, FURGONETA o BICICLETA_ELECTRICA' 
;

COMMENT ON COLUMN TIPO_VEHICULO.CAPACIDAD_MAX_KG IS 'Carga máxima del tipo' 
;

ALTER TABLE TIPO_VEHICULO 
    ADD CONSTRAINT TIPO_VEHICULO_PK PRIMARY KEY ( ID_TIPO_VEHICULO )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

ALTER TABLE TIPO_VEHICULO 
    ADD CONSTRAINT TIPO_VEHICULO_NOMBRE_UK UNIQUE ( NOMBRE )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE VEHICULO 
    ( 
     ID_VEHICULO      NUMBER (5) GENERATED BY DEFAULT AS IDENTITY NOT NULL , 
     ID_CENTRO        NUMBER (5)  NOT NULL , 
     ID_TIPO_VEHICULO NUMBER (2)  NOT NULL , 
     PLACA            VARCHAR2 (10) , 
     MARCA            VARCHAR2 (40)  NOT NULL , 
     MODELO           VARCHAR2 (40)  NOT NULL , 
     CAPACIDAD_KG     NUMBER (6,1)  NOT NULL , 
     ELECTRICO        CHAR (1)  NOT NULL , 
     ESTADO           VARCHAR2 (20) DEFAULT 'DISPONIBLE'  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

ALTER TABLE VEHICULO 
    ADD CONSTRAINT VEHICULO_CAPACIDAD_CK 
    CHECK (CAPACIDAD_KG > 0) 
;

ALTER TABLE VEHICULO 
    ADD CONSTRAINT VEHICULO_ELECTRICO_CK 
    CHECK (ELECTRICO IN ('N', 'S')) 
;

ALTER TABLE VEHICULO 
    ADD CONSTRAINT VEHICULO_ESTADO_CK 
    CHECK (ESTADO IN ('DISPONIBLE', 'EN_MANTENIMIENTO', 'FUERA_SERVICIO')) 
;

COMMENT ON TABLE VEHICULO IS 'Vehículo de la flota.'
;

COMMENT ON COLUMN VEHICULO.ID_VEHICULO IS 'Identificador' 
;

COMMENT ON COLUMN VEHICULO.ID_CENTRO IS 'Centro al que está asignado (ref. centro_distribucion)' 
;

COMMENT ON COLUMN VEHICULO.ID_TIPO_VEHICULO IS 'Tipo de vehículo (ref. tipo_vehiculo)' 
;

COMMENT ON COLUMN VEHICULO.PLACA IS 'Placa (nula en bicicletas)' 
;

COMMENT ON COLUMN VEHICULO.MARCA IS 'Marca' 
;

COMMENT ON COLUMN VEHICULO.MODELO IS 'Modelo' 
;

COMMENT ON COLUMN VEHICULO.CAPACIDAD_KG IS 'Carga máxima del vehículo' 
;

COMMENT ON COLUMN VEHICULO.ELECTRICO IS 'S o N' 
;

COMMENT ON COLUMN VEHICULO.ESTADO IS 'DISPONIBLE, EN_MANTENIMIENTO o FUERA_SERVICIO; por defecto DISPONIBLE' 
;

ALTER TABLE VEHICULO 
    ADD CONSTRAINT VEHICULO_PK PRIMARY KEY ( ID_VEHICULO )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

ALTER TABLE VEHICULO 
    ADD CONSTRAINT VEHICULO_PLACA_UK UNIQUE ( PLACA )
    USING INDEX TABLESPACE TS_ENLACE_INDICES ;

CREATE TABLE ZONA 
    ( 
     ID_ZONA     NUMBER (5) GENERATED BY DEFAULT AS IDENTITY NOT NULL , 
     ID_CENTRO   NUMBER (5)  NOT NULL , 
     NOMBRE      VARCHAR2 (60)  NOT NULL , 
     LOCALIDADES VARCHAR2 (200)  NOT NULL 
    ) 
    TABLESPACE TS_ENLACE_DATOS 
    LOGGING 
;

COMMENT ON TABLE ZONA IS 'Sector de la ciudad atendido por un centro.'
;

COMMENT ON COLUMN ZONA.ID_ZONA IS 'Identificador de la zona' 
;

COMMENT ON COLUMN ZONA.ID_CENTRO IS 'Centro que atiende la zona (ref. centro_distribucion)' 
;

COMMENT ON COLUMN ZONA.NOMBRE IS 'Nombre de la zona' 
;

COMMENT ON COLUMN ZONA.LOCALIDADES IS 'Localidades que cubre' 
;

